// Build a bounded-size random BPF program, validate it, then run it on a random packet buffer.
// 1) Generate up to 32 random instructions; we will use a random prefix length in [1,32].
const bpf_insn (*prog_arr)[32] = FUZZ_PARAM(bpf_insn[32]);
const bpf_insn *program = &(*prog_arr)[0];
int prog_len = (int)(*FUZZ_PARAM(unsigned int) % 32) + 1; // [1,32]

// 2) Validate the program for safety before executing.
if (bpf_validate(program, prog_len) == 0) {
    // Invalid/unsafe program; do not execute per requirements.
    FUZZ_BAIL();
}

// 3) Generate a packet buffer using FUZZ_PARAM_STR(). Size is in [1,4096].
std::string pkt = FUZZ_PARAM_STR();

// 4) Choose buflen within the available buffer; allow 0 to test NULL packet behavior.
unsigned int max_buf = (unsigned int)pkt.size();
unsigned int buflen = (max_buf == 0) ? 0U : (*FUZZ_PARAM(unsigned int) % (max_buf + 1));

// 5) Choose wirelen >= buflen. Cap the additional delta to keep it small.
unsigned int extra = *FUZZ_PARAM(unsigned int) % 1501; // up to 1500 extra bytes
unsigned int wirelen = buflen + extra;

// 6) packet pointer must be valid when buflen > 0; may be NULL when buflen == 0.
const u_char *packet_ptr = (buflen > 0) ? reinterpret_cast<const u_char *>(pkt.data()) : nullptr;

// 7) Execute the filter. Return value semantics are up to the caller; no assertions here.
volatile u_int result = bpf_filter(program, packet_ptr, wirelen, buflen);
(void)result;

// Validation summary:
// - Program length constrained to [1,32] and validated via bpf_validate(); bail if invalid.
// - packet pointer and lengths respect API: NULL only if buflen==0; wirelen >= buflen.

// Build a bounded-size random BPF instruction array and call bpf_validate().
// 1) Generate up to 64 instructions; validate a random prefix in [0,64].
const bpf_insn (*insn_arr)[64] = FUZZ_PARAM(bpf_insn[64]);
const bpf_insn *f = &(*insn_arr)[0];
int len = (int)(*FUZZ_PARAM(unsigned int) % 65); // [0,64] per requirement len >= 0

// 2) Validate; callers must check the return value. We do not assert here.
volatile int ok = bpf_validate(f, len);
(void)ok;

// Validation summary:
// - f points to an array with at least len elements; len is >= 0 and <= 64.

// Construct a small BPF program, validate it, then dump its disassembly.
// 1) Create up to 32 random instructions and choose a valid program length in [1,32].
const bpf_insn (*arr)[32] = FUZZ_PARAM(bpf_insn[32]);
int len = (int)(*FUZZ_PARAM(unsigned int) % 32) + 1; // [1,32]

// 2) Validate the program before dumping.
const bpf_insn *f = &(*arr)[0];
if (bpf_validate(f, len) == 0) {
    // Don't attempt to dump invalid/unsafe programs.
    FUZZ_BAIL();
}

// 3) Build a bpf_program wrapper referencing our instruction array.
bpf_program prog;
prog.bf_len = (u_int)len;
prog.bf_insns = const_cast<bpf_insn *>(f); // API expects non-const; instructions remain unchanged.

// 4) Choose an arbitrary formatting option and call bpf_dump().
int option = *(FUZZ_PARAM(int));
bpf_dump(&prog, option);

// Validation summary:
// - Program pointer and length are valid and pre-validated; option arbitrary; no ownership is transferred.

// Disassemble a single BPF instruction to a human-readable string.
// FUZZ_PARAM cannot produce struct types directly, so use an array and pick one element.
const bpf_insn (*insn_arr)[8] = FUZZ_PARAM(bpf_insn[8]);
unsigned int idx = *FUZZ_PARAM(unsigned int) % 8; // select a valid element
const bpf_insn *insn = &(*insn_arr)[idx];

// Select an arbitrary formatting/verbosity option (semantics implementation-defined).
int option = *(FUZZ_PARAM(int));

// Call bpf_image; returned storage is treated as read-only and not freed (ownership unspecified).
char *text = bpf_image(insn, option);
(void)text;

// Validation summary:
// - Non-null pointer to a valid bpf_insn is provided via array element; option arbitrary; return value is not modified/freed.

// Generate a hostname string. It must be null-terminated; c_str() guarantees that.
std::string host = FUZZ_PARAM_STR();
const char *h = host.c_str();
// Call resolver. It may return NULL if not found; that's acceptable.
u_char *mac = pcap_ether_hostton(h);
// If non-NULL, it points to 6 bytes in static storage; do not free or persist beyond subsequent calls.
(void)mac;

// Generate a candidate MAC string. Common forms include aa:bb:cc:dd:ee:ff, but parser defines acceptance.
std::string macstr = FUZZ_PARAM_STR();
const char *s = macstr.c_str();
// Parse; may return NULL on format error. That's acceptable.
u_char *addr6 = pcap_ether_aton(s);
// If non-NULL, points to 6 bytes in static storage; do not free.
(void)addr6;

// Generate a hostname to resolve. Must be null-terminated.
std::string host = FUZZ_PARAM_STR();
const char *h = host.c_str();
// Deprecated, not reentrant; returns static storage. May return NULL on failure.
bpf_u_int32 **addrs = pcap_nametoaddr(h);
// Caller must not assume formatting; do not dereference if NULL.
(void)addrs;

// Generate a network name string.
std::string net = FUZZ_PARAM_STR();
const char *n = net.c_str();
// Return value semantics and byte order are implementation-defined; just call it.
bpf_u_int32 netaddr = pcap_nametonetaddr(n);
(void)netaddr;

// Generate a service/port specification string.
std::string svc = FUZZ_PARAM_STR();
const char *s = svc.c_str();
// Prepare non-NULL out-parameters as required by API.
int port = 0;
int proto = 0;
// Call the function. Return semantics unspecified; do not assert. Outputs are meaningful on success.
int rv = pcap_nametoport(s, &port, &proto);
(void)rv; (void)port; (void)proto;

// Generate a port range/service-range specification string.
std::string spec = FUZZ_PARAM_STR();
const char *ps = spec.c_str();
// Prepare required non-NULL out-parameters.
int low = 0;
int high = 0;
int proto = 0;
// Call the function. It may fail (returns error or sets PROTO_UNDEF); both are acceptable.
int rv = pcap_nametoportrange(ps, &low, &high, &proto);
// Quick sanity: if it claims success (rv == 0 or >0 depending on impl), ensure range order if both set.
// We do not enforce as an invariant since semantics are unspecified; just consume values.
(void)rv; (void)low; (void)high; (void)proto;

// Generate a protocol name string (e.g., "tcp", "udp", "icmp").
std::string pname = FUZZ_PARAM_STR();
const char *p = pname.c_str();
int proto = pcap_nametoproto(p);
// PROTO_UNDEF (-1) indicates unknown; both outcomes are acceptable.
(void)proto;

// Generate an Ethernet protocol name (e.g., "ip", "arp").
std::string ename = FUZZ_PARAM_STR();
const char *e = ename.c_str();
int eproto = pcap_nametoeproto(e);
// PROTO_UNDEF (-1) indicates unknown; both outcomes are acceptable.
(void)eproto;

// Generate an LLC protocol name string.
std::string lname = FUZZ_PARAM_STR();
const char *l = lname.c_str();
int llc = pcap_nametollc(l);
// PROTO_UNDEF (-1) indicates unknown; both outcomes are acceptable.
(void)llc;

// Open a random data file path and try to use it as an ethers database source.
// Use a readable FILE*; if open fails, bail since preconditions aren't met.
const char *fname = FUZZ_PARAM_FILENAME();
FILE *fp = fopen(fname, "r");
if (!fp) { FUZZ_BAIL(); }

// Invoke the target. It may return NULL on EOF/parse error; that's acceptable.
struct pcap_etherent *ent = pcap_next_etherent(fp);
(void)ent; // Do not free; storage is likely static per API.

// Close the stream to avoid leaks; ent (if non-NULL) remains valid as static storage.
(void)fclose(fp);
// No persistent outputs.

// Generate a hostname to resolve (null-terminated via c_str()).
std::string host = FUZZ_PARAM_STR();
const char *h = host.c_str();

// Reentrant resolver; returns a list we must free with freeaddrinfo().
struct addrinfo *ai = pcap_nametoaddrinfo(h);

// ai may be NULL on failure; that's acceptable. If non-NULL, free it to avoid leaks.
if (ai) { freeaddrinfo(ai); }
// No persistent outputs.

// Generate a valid opts bitmask limited to a few low bits to avoid reserved values.
unsigned int opts = *FUZZ_PARAM(unsigned int) & 0x7u; // keep within expected PCAP_* flags subset
// errbuf must be at least PCAP_ERRBUF_SIZE; allocate a fixed-size stack buffer via std::string
std::string err(256, '\0');
int rc = pcap_init(opts, err.data());
(void)rc; // caller must check; here we exercise the API path
// Validation: errbuf is non-null and sized >=256; opts constrained to a small mask. No persistent objects to output.

// Prepare an error buffer of sufficient size
std::string err(256, '\0');
char *dev = pcap_lookupdev(err.data());
(void)dev; // may be NULL on error; err contains details
// Validation: errbuf provided and sized; return value is transient and not persisted.

// device may be NULL; provide a random device name string sometimes empty
std::string dev_str = FUZZ_PARAM_STR();
const char *device = (dev_str.size() % 3 == 0) ? nullptr : dev_str.c_str();
bpf_u_int32 net = 0, mask = 0;
std::string err(256, '\0');
int rc = pcap_lookupnet(device, &net, &mask, err.data());
(void)rc; (void)net; (void)mask;
// Validation: netp/maskp are valid pointers; errbuf sized; device may be NULL per API.

// device should be a capture device name; use fuzz string
std::string dev = FUZZ_PARAM_STR();
std::string err(256, '\0');
pcap_t *p = pcap_create(dev.c_str(), err.data());
if (!p) { FUZZ_BAIL(); }
// Newly created handles are inactive until activated
FUZZ_SET_ATTR_STR(p, "state", "inactive");
// Output p for further configuration/activation.

// Must be called on an inactive handle
int is_inactive = !strcmp(FUZZ_GET_ATTR_STR(p, "state"), "inactive");
if (!is_inactive) { FUZZ_BAIL(); }
// Choose a reasonable non-negative snapshot length (keep small for fuzz performance)
int snaplen = (int)(*FUZZ_PARAM(unsigned int) % 2048u);
int rc = pcap_set_snaplen(p, snaplen);
(void)rc;
// Validation: state enforced inactive; snaplen >= 0; handle persisted.

// Must be called on an inactive handle
int is_inactive = !strcmp(FUZZ_GET_ATTR_STR(p, "state"), "inactive");
if (!is_inactive) { FUZZ_BAIL(); }
int promisc = (int)(*FUZZ_PARAM(unsigned int) & 1u);
int rc = pcap_set_promisc(p, promisc);
(void)rc;
// Validation: state enforced inactive; promisc is 0/1; handle persisted.

// Query capability; allowed on valid handle (commonly inactive)
int rc = pcap_can_set_rfmon(p);
(void)rc;
// Validation: no state change; handle persisted for subsequent calls.

// Must be called on an inactive handle
int is_inactive = !strcmp(FUZZ_GET_ATTR_STR(p, "state"), "inactive");
if (!is_inactive) { FUZZ_BAIL(); }
int rfmon = (int)(*FUZZ_PARAM(unsigned int) & 1u);
int rc = pcap_set_rfmon(p, rfmon);
(void)rc;
// Validation: state enforced inactive; rfmon 0/1 set; handle persisted.

// Must be called on an inactive handle
int is_inactive = !strcmp(FUZZ_GET_ATTR_STR(p, "state"), "inactive");
if (!is_inactive) { FUZZ_BAIL(); }
int to_ms = (int)(*FUZZ_PARAM(unsigned int) % 2000u); // >= 0
int rc = pcap_set_timeout(p, to_ms);
(void)rc;
// Validation: non-negative timeout; inactive enforced; handle persisted.

// Must be called on an inactive handle
int is_inactive = !strcmp(FUZZ_GET_ATTR_STR(p, "state"), "inactive");
if (!is_inactive) { FUZZ_BAIL(); }
// Use a small domain of possible types
