int rc = pcap_set_tstamp_type(p, tstamp_type);
(void)rc;
// Validation: inactive enforced; tstamp_type constrained; handle persisted.

// Must be called on an inactive handle
int is_inactive = !strcmp(FUZZ_GET_ATTR_STR(p, "state"), "inactive");
if (!is_inactive) { FUZZ_BAIL(); }
int immediate = (int)(*FUZZ_PARAM(unsigned int) & 1u);
int rc = pcap_set_immediate_mode(p, immediate);
(void)rc;
// Validation: inactive enforced; parameter 0/1; handle persisted.

// Must be called on an inactive handle
int is_inactive = !strcmp(FUZZ_GET_ATTR_STR(p, "state"), "inactive");
if (!is_inactive) { FUZZ_BAIL(); }
// Positive buffer size; keep modest for fuzzing
int buffer_size = (int)(*FUZZ_PARAM(unsigned int) % 2048u) + 1;
int rc = pcap_set_buffer_size(p, buffer_size);
(void)rc;
// Validation: inactive enforced; buffer_size > 0; handle persisted.

// Must be called on an inactive handle
int is_inactive = !strcmp(FUZZ_GET_ATTR_STR(p, "state"), "inactive");
if (!is_inactive) { FUZZ_BAIL(); }
// Precision must be MICRO(0) or NANO(1)
int prec = (int)(*FUZZ_PARAM(unsigned int) & 1u);
int rc = pcap_set_tstamp_precision(p, prec);
(void)rc;
// Validation: inactive enforced; precision constrained to {0,1}; handle persisted.

// Should be called on an active (or offline) handle; enforce active in this harness
int is_active = !strcmp(FUZZ_GET_ATTR_STR(p, "state"), "active");
if (!is_active) { FUZZ_BAIL(); }
int prec = pcap_get_tstamp_precision(p);
(void)prec;
// Validation: active enforced; return value consumed; handle persisted.

// Must be called on an inactive, not-yet-activated handle
int is_inactive = !strcmp(FUZZ_GET_ATTR_STR(p, "state"), "inactive");
if (!is_inactive) { FUZZ_BAIL(); }
int rc = pcap_activate(p);
// On success (>=0), the handle becomes active; on error (<0) it remains inactive
if (rc >= 0) {
    FUZZ_SET_ATTR_STR(p, "state", "active");
}
// Validation: state transition applied only on non-negative return; handle persisted.

