int v = pcap_tstamp_type_name_to_val(name.c_str());
(void)v;
// Validation: exercised mapping; no persistent state.

// Provide a small integer domain to hit known/unknown values
int t = (int)(*FUZZ_PARAM(unsigned int) % 16u);
const char *s = pcap_tstamp_type_val_to_name(t);
(void)s;
// Validation: returned pointer may be NULL; not used beyond this point.

int t = (int)(*FUZZ_PARAM(unsigned int) % 16u);
const char *s = pcap_tstamp_type_val_to_description(t);
(void)s;
// Validation: returned pointer may be NULL; not used beyond this point.

// Prepare parameters
std::string dev = FUZZ_PARAM_STR();
int snaplen = (int)(*FUZZ_PARAM(unsigned int) % 2048u); // non-negative, small for fuzz perf
int promisc = (int)(*FUZZ_PARAM(unsigned int) & 1u);
