FUZZ_SET_ATTR_STR(p, "state", "active");
FUZZ_SET_ATTR_STR(p, "kind", "live");
// Validation: errbuf provided; parameters constrained; non-null handle returned and marked active.

// Choose a plausible linktype and snaplen
int linktype = (int)(*FUZZ_PARAM(unsigned int) % 256u);
int snaplen  = (int)(*FUZZ_PARAM(unsigned int) % 2048u);
pcap_t *p = pcap_open_dead(linktype, snaplen);
if (!p) { FUZZ_BAIL(); }
