import random
import string

# Generator for valid/interesting MAC address strings to feed pcap_ether_aton()
# Returns bytes (ASCII) of a null-terminated textual MAC address in various common formats.

HEX_LOWER = "0123456789abcdef"
HEX_UPPER = "0123456789ABCDEF"

def _rand_hex_pair(rng, upper=False):
    alphabet = HEX_UPPER if upper else HEX_LOWER
    return rng.choice(alphabet) + rng.choice(alphabet)

def _format_colon_separated(rng):
    # aa:bb:cc:dd:ee:ff (lower/upper/mixed)
    case = rng.choice(["lower", "upper", "mixed"])
    parts = []
    for _ in range(6):
        if case == "lower":
            parts.append(_rand_hex_pair(rng, upper=False))
        elif case == "upper":
            parts.append(_rand_hex_pair(rng, upper=True))
        else:
            # mixed case per nibble
            p = "".join(rng.choice([c.lower(), c.upper()]) for c in _rand_hex_pair(rng))
            parts.append(p)
    return ":".join(parts)

def _format_hyphen_separated(rng):
    # aa-bb-cc-dd-ee-ff
    parts = [_rand_hex_pair(rng, upper=rng.random()<0.5) for _ in range(6)]
    # Optionally mixed case tweak
    if rng.random() < 0.3:
        parts = ["".join(rng.choice([c.lower(), c.upper()]) for c in p) for p in parts]
    return "-".join(parts)

def _format_dot_quartet(rng):
    # Cisco style: aabb.ccdd.eeff (3 groups of 4 hex)
    groups = []
    for _ in range(3):
        g = "".join(rng.choice(HEX_LOWER + HEX_UPPER) for _ in range(4))
        groups.append(g)
    return ".".join(groups)

def _format_plain12(rng):
    # aabbccddeeff (12 hex digits)
    return "".join(rng.choice(HEX_LOWER + HEX_UPPER) for _ in range(12))

def _format_0x_prefixed_pairs(rng):
    # 0xaa:0xbb:0xcc:0xdd:0xee:0xff (some parsers accept 0x prefix per octet)
    parts = ["0x" + _rand_hex_pair(rng, upper=rng.random()<0.5) for _ in range(6)]
    return ":".join(parts)

def _format_with_whitespace(rng, base_formatter):
    # Surround with optional leading/trailing whitespace; maybe internal spaces around separators
    s = base_formatter(rng)
    # Optionally add spaces around separators for colon/hyphen formats
    if rng.random() < 0.3:
        s = s.replace(":", rng.choice([" :", ": ", " : "]))
        s = s.replace("-", rng.choice([" -", "- ", " - "]))
        s = s.replace(".", rng.choice([" .", ". ", " . "]))
    # Leading/trailing whitespace variants
    lead = "".join(rng.choice([" ", "\t"]) for _ in range(rng.randint(0, 2)))
    trail = "".join(rng.choice([" ", "\t"]) for _ in range(rng.randint(0, 2)))
    return lead + s + trail

def _format_with_separators_variants(rng):
    # Occasionally mix separators within valid positions (some parsers may accept)
    # Build six octets then join with a random mix of ':' and '-' (still 5 separators)
    octets = [_rand_hex_pair(rng, upper=rng.random()<0.5) for _ in range(6)]
    seps = [rng.choice([':', '-']) for _ in range(5)]
    out = []
    for i, o in enumerate(octets):
        out.append(o)
        if i < 5:
            out.append(seps[i])
    return "".join(out)

def _format_eui64_like(rng):
    # Some parsers might accept 8 octets; but pcap_ether_aton expects 6.
    # To remain valid, generate 6 but sometimes embed VLAN-like label to test parser robustness: aa:bb:cc:dd:ee:ff%eth0
    base = _format_colon_separated(rng)
    if rng.random() < 0.2:
        base += rng.choice(["%eth0", "%1", "%enp3s0"])  # zone id style suffix
    return base

def _generate_valid_mac_string(rng):
    # Weighted selection of common and less-common formats
    choices = [
        (_format_colon_separated, 0.35),
        (_format_hyphen_separated, 0.2),
        (_format_dot_quartet, 0.15),
        (_format_plain12, 0.15),
        (_format_0x_prefixed_pairs, 0.05),
        (_format_with_separators_variants, 0.05),
        (_format_eui64_like, 0.05),
    ]
    r = rng.random()
    acc = 0.0
    for fmt, w in choices:
        acc += w
        if r <= acc:
            s = fmt(rng)
            break
    else:
        s = _format_colon_separated(rng)

    # Optionally wrap with whitespace
    if rng.random() < 0.4:
        s = _format_with_whitespace(rng, lambda _rng: s)

    return s

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Generate between 1 and 3 candidate MAC strings concatenated with newlines to help fuzzers split
    count = 1 if rng.random() < 0.7 else rng.randint(2, 3)
    items = []
    for _ in range(count):
        mac = _generate_valid_mac_string(rng)
        items.append(mac)

    payload = "\n".join(items)

    # Ensure <= 4096 bytes
    b = payload.encode('ascii', errors='ignore')[:4095]
    # Add a terminating newline occasionally to provide a clean token end
    if rng.random() < 0.5 and len(b) < 4095:
        b += b"\n"
    return b

import random
import string
from typing import List, Tuple

# Generator for valid/interesting port-range/service-range specifications
# to exercise pcap_nametoportrange(const char*, int*, int*, int*).
# The fuzzer stub passes our bytes to FUZZ_PARAM_STR(), so we should
# return bytes that decode to a plausible C string. We'll restrict to ASCII.

PORT_NAMES_TCP = [
    # common TCP services
    "http", "https", "ssh", "telnet", "smtp", "submission", "pop3", "imap", "imap3",
    "ftp", "ftps", "mysql", "postgresql", "mssql", "rdp", "ldap", "ldaps", "kerberos",
    "ntp", "snmp", "snmptrap", "sip", "irc", "xmpp", "redis", "memcached", "amqp",
]

PORT_NAMES_UDP = [
    # common UDP services
    "domain", "dhcp", "tftp", "snmp", "ntp", "syslog", "rip", "isakmp", "ikev2",
    "mdns", "ssdp", "snmptrap", "snmp-trap",
]

# Some ambiguous or proto-suffixed forms various stacks might parse
QUALIFIERS = [
    "tcp", "udp", "sctp", "udplite",
]

# Some separators and syntaxes that implementations often accept
SEPARATORS = ["-", ":", ",", " .. ", " to "]

# Range keywords that some implementations might accept
RANGE_WORDS = ["range", "ports", "portrange", "between"]

# Helper to pick a port number respecting valid range 0..65535

def rand_port(rng: random.Random) -> int:
    # Bias to include boundary values and typical ports
    choices = [0, 1, 7, 9, 13, 19, 20, 21, 22, 23, 25, 37, 42, 43, 53, 67, 68,
               69, 80, 110, 123, 137, 138, 139, 143, 161, 162, 179, 389, 443,
               993, 995, 1433, 1521, 2049, 3306, 3389, 5432, 6379, 8080, 9000,
               49152, 65535]
    if rng.random() < 0.6:
        return rng.choice(choices)
    return rng.randint(0, 65535)


def maybe(proto: str, sep: str, value: str, rng: random.Random) -> str:
    # sometimes prepend or append a protocol qualifier
    style = rng.randint(0, 4)
    if style == 0:
        return value
    if style == 1:
        return f"{proto}{sep}{value}"
    if style == 2:
        return f"{value}{sep}{proto}"
    if style == 3:
        return f"{proto} {value}"
    return f"{value} {proto}"


def numeric_range(rng: random.Random) -> str:
    a = rand_port(rng)
    # sometimes create reversed range to test normalization
    if rng.random() < 0.2:
        b = a - rng.randint(0, 5000)
    else:
        b = rand_port(rng)
    sep = rng.choice(SEPARATORS[:2])  # common separators: '-' or ':'
    return f"{a}{sep}{b}"


def wordy_range(rng: random.Random) -> str:
    a = rand_port(rng)
    b = rand_port(rng)
    word = rng.choice(RANGE_WORDS)
    sep = rng.choice([" ", "  ", "\t"])  # whitespace variety
    # Formats like: "range 1000-2000", "ports 53 to 67", "between 80 and 90"
    style = rng.randint(0, 2)
    if style == 0:
        return f"{word}{sep}{a}-{b}"
    if style == 1:
        mid = rng.choice(["to", "..", "-", "and"])
        return f"{word}{sep}{a}{sep}{mid}{sep}{b}"
    return f"{word}{sep}{a}:{b}"


def service_single(rng: random.Random) -> str:
    # just a single service name, often implies a single port
    if rng.random() < 0.5:
        name = rng.choice(PORT_NAMES_TCP)
    else:
        name = rng.choice(PORT_NAMES_UDP)
    # maybe include explicit proto qualifier like "http/tcp"
    style = rng.randint(0, 3)
    if style == 0:
        return name
    if style == 1:
        return f"{name}/tcp"
    if style == 2:
        return f"{name}/udp"
    return f"{name} {rng.choice(QUALIFIERS)}"


def service_range(rng: random.Random) -> str:
    # Combine two service names as a range in different separators
    left = rng.choice(PORT_NAMES_TCP + PORT_NAMES_UDP)
    right = rng.choice(PORT_NAMES_TCP + PORT_NAMES_UDP)
    sep = rng.choice(SEPARATORS)
    s = f"{left}{sep}{right}"
    # maybe add proto qualifier
    if rng.random() < 0.6:
        proto = rng.choice(QUALIFIERS)
        s = maybe(proto, '/', s, rng)
    return s


def mixed_numeric_service(rng: random.Random) -> str:
    # Mix a number and a service as a range
    if rng.random() < 0.5:
        left = str(rand_port(rng))
        right = rng.choice(PORT_NAMES_TCP + PORT_NAMES_UDP)
    else:
        left = rng.choice(PORT_NAMES_TCP + PORT_NAMES_UDP)
        right = str(rand_port(rng))
    sep = rng.choice(SEPARATORS[:3])
    s = f"{left}{sep}{right}"
    if rng.random() < 0.5:
        s = maybe(rng.choice(QUALIFIERS), '/', s, rng)
    return s


def list_of_ranges(rng: random.Random) -> str:
    # Some stacks accept comma-separated lists; include spaces variations
    parts = []
    n = rng.randint(2, 4)
    for _ in range(n):
        choice = rng.random()
        if choice < 0.34:
            parts.append(numeric_range(rng))
        elif choice < 0.67:
            parts.append(service_single(rng))
        else:
            parts.append(mixed_numeric_service(rng))
    sep = rng.choice([",", ", ", ",\t", "; "])
    s = sep.join(parts)
    if rng.random() < 0.4:
        s = maybe(rng.choice(QUALIFIERS), '/', s, rng)
    return s


def single_number_with_proto(rng: random.Random) -> str:
    p = rand_port(rng)
    style = rng.randint(0, 4)
    if style == 0:
        return str(p)
    if style == 1:
        return f"{p}/tcp"
    if style == 2:
        return f"{p}/udp"
    if style == 3:
        return f"tcp/{p}"
    return f"udp:{p}"


def decorate(s: str, rng: random.Random) -> str:
    # Optionally add surrounding whitespace, quotes, or brackets some parsers allow
    # Keep it simple to remain likely valid
    if rng.random() < 0.2:
        s = s.strip()
    if rng.random() < 0.25:
        s = s + "\n"  # trailing newline common in files
    if rng.random() < 0.15:
        s = " " * rng.randint(0, 3) + s + " " * rng.randint(0, 3)
    return s


def build_spec(rng: random.Random) -> str:
    builders = [
        numeric_range,
        wordy_range,
        service_single,
        service_range,
        mixed_numeric_service,
        list_of_ranges,
        single_number_with_proto,
    ]
    # Bias toward simpler, very likely-valid formats
    weights = [0.25, 0.05, 0.2, 0.15, 0.15, 0.1, 0.1]
    choice = rng.random()
    acc = 0.0
    for b, w in zip(builders, weights):
        acc += w
        if choice < acc:
            s = b(rng)
            return decorate(s, rng)
    s = builders[-1](rng)
    return decorate(s, rng)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    s = build_spec(rng)
    # Ensure size limit and ASCII encoding; null-termination is not required as fuzz harness handles strings,
    # but keep content <= 4096 bytes.
    if len(s) > 4096:
        s = s[:4096]
    return s.encode('ascii', errors='ignore')

import random
import string
from typing import List

# This generator produces plausible interface name strings for libpcap APIs
# that expect device/interface identifiers or components of pcap source strings.
# It attempts to cover a variety of OS naming conventions and pcap source URL forms.

MAX_LEN = 256

_STD_PREFIXES = [
    # Linux common
    "eth", "enp", "ens", "eno", "wlx", "wlan", "wwp", "usb", "lo",
    # BSD/macOS common
    "en", "awdl", "llw", "utun", "bridge", "gif", "stf", "ap", "p2p",
    # Windows NPF/NPcap style (Display names not used by pcap APIs, but adapter GUIDs can be)
    # We'll also synthesize GUID-like names when needed.
]

# Common pcap open source URL schemes
_SRC_SCHEMES = [
    # Local file
    "file://",
    # Local interface (explicit type)
    "rpcap://",           # remote capture
    "rpcap://user:pass@", # remote with credentials in URL
    # Empty string to allow raw device names
    "",
]

# Named pipes/loopback or special pseudo devices some stacks expose
_SPECIAL_DEVICES = [
    "any",          # Linux "any" pseudo-device
    "lo",           # loopback (Linux)
    "lo0",          # loopback (BSD/macOS)
    "null",         # some platforms accept special devices
]

_ETHERTYPES = ["ip", "arp", "ipv6"]  # occasionally used in sources but here for variety in names

def _rand_mac_like(r: random.Random) -> str:
    return ":".join(f"{r.randrange(0,256):02x}" for _ in range(6))

def _rand_guid(r: random.Random) -> str:
    # Windows adapter GUID-like
    def seg(n):
        return ''.join(r.choice('0123456789abcdef') for _ in range(n))
    return f"{{{seg(8)}-{seg(4)}-{seg(4)}-{seg(4)}-{seg(12)}}}"

def _linux_ifname(r: random.Random) -> str:
    pref = r.choice(["eth", "enp", "ens", "eno", "wlan", "wlx", "wwp", "usb"]) 
    if pref in ("enp", "ens", "eno"):
        # Predictable interface names: enp3s0, ens33, eno1
        a = r.randrange(0, 9)
        b = r.randrange(0, 128)
        # enp<slot>s<func> or ens<num>
        if pref == "enp":
            return f"enp{a}s{b}"
        elif pref == "ens":
            return f"ens{b}"
        else:
            return f"eno{a}"
    elif pref == "wlx":
        # wlx<mac>
        mac = ''.join(f"{r.randrange(0,256):02x}" for _ in range(6))
        return f"wlx{mac}"
    elif pref == "usb":
        # usbX
        return f"usb{r.randrange(0,16)}"
    elif pref == "wwp":
        return f"wwp{r.randrange(0,8)}s{r.randrange(0,8)}"
    elif pref == "wlan":
        return f"wlan{r.randrange(0,16)}"
    else:
        return f"eth{r.randrange(0,16)}"

def _bsd_macos_ifname(r: random.Random) -> str:
    pref = r.choice(["en", "awdl", "llw", "utun", "bridge", "ap", "p2p"]) 
    if pref in ("en", "awdl", "llw", "utun", "ap", "p2p"):
        return f"{pref}{r.randrange(0, 64)}"
    elif pref == "bridge":
        return f"bridge{r.randrange(0, 32)}"
    else:
        return f"{pref}{r.randrange(0, 64)}"

def _windows_ifname(r: random.Random) -> str:
    # NPCap/WinPcap raw device typically uses NPF_ names internally, but pcap APIs
    # often take the textual GUID form like "\\Device\\NPF_{GUID}" or just GUID.
    guid = _rand_guid(r)
    if r.random() < 0.5:
        return f"\\\\Device\\\\NPF_{guid.strip('{}')}"
    else:
        return guid

def _random_device_name(r: random.Random) -> str:
    # Mix of realistic device names and special devices
    choice = r.random()
    if choice < 0.35:
        return _linux_ifname(r)
    elif choice < 0.6:
        return _bsd_macos_ifname(r)
    elif choice < 0.8:
        return _windows_ifname(r)
    else:
        return r.choice(_SPECIAL_DEVICES)

def _random_file_like(r: random.Random) -> str:
    # Return a plausible file path (for pcap_open_offline/pcap_createsrcstr with PCAP_SRC_FILE)
    base = r.choice(["capture", "trace", "dump", "pcapfile", "session"]) + str(r.randrange(0, 1000))
    ext = r.choice([".pcap", ".cap", ".pcapng"])  # even if code under test may expect .pcap
    path = r.choice([
        f"/tmp/{base}{ext}",
        f"/var/tmp/{base}{ext}",
        f"./{base}{ext}",
    ])
    return path

def _random_rpcap_source(r: random.Random) -> str:
    # Build an rpcap URL with optional auth and name
    host = r.choice([
        "localhost", "127.0.0.1", "::1", "capture.example.com", "192.168.1.10"
    ])
    port = r.choice(["", ":2002", ":80", ":443"])  # rpcap default is 2002
    userpass = ""
    if r.random() < 0.3:
        user = ''.join(r.choice(string.ascii_letters) for _ in range(r.randrange(3, 8)))
        pwd = ''.join(r.choice(string.ascii_letters + string.digits) for _ in range(r.randrange(4, 10)))
        userpass = f"{user}:{pwd}@"
    name = _random_device_name(r)
    return f"rpcap://{userpass}{host}{port}/{name}"

def _random_source_string(r: random.Random) -> str:
    # Sometimes return plain device name, sometimes a file://, sometimes rpcap://
    t = r.random()
    if t < 0.55:
        return _random_device_name(r)
    elif t < 0.75:
        return "file://" + _random_file_like(r)
    else:
        return _random_rpcap_source(r)

def _maybe_nullish(r: random.Random, s: str) -> str:
    # The fuzzer stub sometimes passes nullptr by making the string length %3==0.
    # We can bias some strings to have length %3==0 to trigger that path.
    if not s:
        return s
    if r.random() < 0.3:
        # Pad to make len % 3 == 0
        rem = (-len(s)) % 3
        if rem:
            s = s + ("_" * rem)
    return s

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Build a small corpus of candidate strings to be consumed by FUZZ_PARAM_STR in order
    # across multiple stubs: pcap_lookupnet, pcap_create, pcap_open_live, pcap_createsrcstr.
    candidates: List[str] = []

    # 1) A plain device name (possibly nullish-triggering) for pcap_lookupnet
    s1 = _maybe_nullish(r, _random_device_name(r))
    candidates.append(s1)

    # 2) A plausible live device for pcap_create
    s2 = _random_device_name(r)
    candidates.append(s2)

    # 3) A plausible live device for pcap_open_live
    s3 = _random_device_name(r)
    candidates.append(s3)

    # 4-6) Components for pcap_createsrcstr: host, port, name
    # We provide varied values, with some NULL-trigger lengths.
    host = _maybe_nullish(r, r.choice(["", "localhost", "192.168.0.1", "::1", "capture.example.org"]))
    port = _maybe_nullish(r, r.choice(["", "80", "2002", "443"]))
    name = _maybe_nullish(r, _random_source_string(r))
    candidates.extend([host, port, name])

    # Add a couple of extras in case harness requests more FUZZ_PARAM_STR calls
    for _ in range(r.randrange(1, 4)):
        candidates.append(_random_source_string(r))

    # Join them with NUL separators so the harness can slice them as independent C strings
    # FUZZ framework usually pulls sequentially; a single buffer with embedded strings is common.
    # Ensure overall size limit
    joined = "\0".join(candidates)
    data = joined.encode('utf-8')
    return data[:4096]

