def gen_addrkey(rng):
    return choice(rng, BPF_PRIMS_ADDRKEY)

def gen_field_cmp(rng):
    # Field comparisons like: tcp[13] & 0x02 != 0, ip[2:2] > 20, ether proto 0x0800
    f = choice(rng, FIELDS)
    # occasionally add a bitmask
    if maybe(rng, 0.4):
        mask = rng.choice([0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x3F,0xFF,0xF0,0x0F])
        op = choice(rng, ["!=", "=="])
        val = rng.choice([0, 1, mask])
        return f"{f} & 0x{mask:02x} {op} {val}"
    else:
        op = choice(rng, REL_OPS[:-1])  # avoid ':' here usually
        val = rng.randrange(0, 256)
        return f"{f} {op} {val}"

def gen_simple_clause(rng):
    kind = rng.randrange(0, 10)
    if kind == 0:
        return gen_proto(rng)
    if kind == 1:
        # dir host/net/port
        dk = gen_dir(rng)
        ak = gen_addrkey(rng)
        if ak == "host":
            if maybe(rng, 0.2):
                return f"{dk} {ak} {gen_v6(rng)}"
            else:
                return f"{dk} {ak} {gen_v4(rng)}"
        if ak == "net":
            return f"{dk} {ak} {choice(rng, NETS_V4)}"
        if ak == "port":
            return f"{dk} {ak} {gen_port(rng)}"
        if ak == "portrange":
            p1 = int(gen_port(rng))
            p2 = p1 + rng.randrange(1, 2000)
            return f"{dk} {ak} {p1}-{min(p2, 65535)}"
    if kind == 2:
        # host without dir
        if maybe(rng, 0.2):
            return f"host {gen_v6(rng)}"
        else:
            return f"host {gen_v4(rng)}"
    if kind == 3:
        # net
        return f"net {choice(rng, NETS_V4)}"
    if kind == 4:
        # port
        return f"port {gen_port(rng)}"
    if kind == 5:
        # ether host
        return f"ether host {gen_eth(rng)}"
    if kind == 6:
        # vlan with optional id
        if maybe(rng, 0.6):
            return f"vlan {rng.randrange(1, 4095)}"
        else:
            return "vlan"
    if kind == 7:
        # pppoed / pppoes subset via proto qualifier plus nested
        inner = gen_proto(rng)
        return f"pppoes and {inner}"
    if kind == 8:
        # qualifiers
        return choice(rng, QUALS)
    # kind == 9: raw field compare
    return gen_field_cmp(rng)

def gen_clause(rng, depth):
    # Build nested clauses with parentheses and logical ops
    if depth <= 0:
        return gen_simple_clause(rng)
    if maybe(rng, 0.5):
        return gen_simple_clause(rng)
    left = gen_clause(rng, depth - 1)
    right = gen_clause(rng, depth - 1)
    op = choice(rng, LOGICALS)
    if maybe(rng, 0.4):
        # sometimes add a not
        if maybe(rng, 0.5):
            left = f"not ({left})"
        else:
            right = f"not ({right})"
    return f"({left}) {op} ({right})"

def gen_filter(rng, target_len):
    # Assemble 1..N clauses
    clauses = []
    n = rng.randrange(1, 6)
    for _ in range(n):
        depth = rng.randrange(0, 3)
        clauses.append(gen_clause(rng, depth))
    # optionally prepend link/proto constraints to increase portability
    if maybe(rng, 0.6):
        prefix = choice(rng, ["ip", "ip6", "ether", "tcp", "udp"])
        clauses.insert(0, prefix)
    expr = " and ".join(clauses)
    # Ensure we do not exceed target_len (leave room for NUL)
    if len(expr.encode('utf-8')) + 1 > target_len:
        # Trim by dropping clauses from the end
        while clauses and len(" and ".join(clauses).encode('utf-8')) + 1 > target_len:
            clauses.pop()
        if not clauses:
            clauses = ["ip"]
        expr = " and ".join(clauses)
    return expr

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Aim for expressions up to ~512 bytes to leave headroom; cap total at 4096
    target_len = rng.randrange(32, 512)
    expr = gen_filter(rng, target_len)
    # Add some common endings to trigger optimizer paths
    tails = [
        "", ")",  # stray paren is invalid; avoid. keep empty only.
        " and tcp dst port 80",
        " or udp port 53",
        " and (icmp or icmp6)",
        " and (tcp[tcpflags] & (tcp-syn) != 0)",  # may or may not be supported; keep rarely
    ]
    # Keep tail selection conservative to favor valid syntax
    tail = choice(rng, tails[:4])  # only pick from the surely-valid subset
    full = expr + tail
    data = full.encode('utf-8') + b"\x00"
    # Final safety: cap at 4096 bytes
    if len(data) > 4096:
        data = data[:4095] + b"\x00"
    return data
